1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { initializeExtension, getTableauUserId } from './lib/tableau';
4	  import { apiFetch, ApiError } from './lib/api';
5	  import { sessionStore } from './stores/session.svelte';
6	  import { statusStore } from './stores/status.svelte';
7	  import StatusBar from './components/StatusBar.svelte';
8	  import AdminConfig from './components/AdminConfig.svelte';
9	
10	  const isAdminView = new URLSearchParams(window.location.search).has('admin');
11	
12	  type AppStatus = 'loading' | 'ready' | 'error';
13	
14	  let appStatus = $state<AppStatus>('loading');
15	  let errorMessage = $state('');
16	
17	  onMount(async () => {
18	    try {
19	      // Step 1: Initialize Tableau runtime
20	      await initializeExtension();
21	
22	      // Step 2: Get Tableau user identity
23	      const tableauUserId = getTableauUserId();
24	      sessionStore.tableauUserId = tableauUserId;
25	
26	      // Step 3: Create backend session
27	      const sessionResponse = await apiFetch<{
28	        data: { session_id: string; started_at: string };
29	      }>('/api/sessions', {
30	        method: 'POST',
31	        body: JSON.stringify({ tableau_user_id: tableauUserId }),
32	      });
33	      sessionStore.sessionId = sessionResponse.data.session_id;
34	
35	      // Step 4: Fetch integration statuses
36	      statusStore.loading = true;
37	      const sessionHeaders: Record<string, string> = {};
38	      if (sessionStore.sessionId) {
39	        sessionHeaders['X-Autom9-Session'] = sessionStore.sessionId;
40	      }
41	      const statusResponse = await apiFetch<{
42	        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
43	      }>('/api/status', {
44	        headers: sessionHeaders,
45	      });
46	
47	      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
48	        name: i.name,
49	        status: i.status as 'healthy' | 'unavailable',
50	        latency_ms: i.latency_ms,
51	        error: i.error,
52	      }));
53	      statusStore.loading = false;
54	
55	      appStatus = 'ready';
56	    } catch (err) {
57	      statusStore.loading = false;
58	      const msg = err instanceof Error ? err.message : 'Extension failed to initialize';
59	      errorMessage = msg;
60	      statusStore.error = msg;
61	      appStatus = 'error';
62	    }
63	  });
64	</script>
65	
66	{#if appStatus === 'loading'}
67	  <div class="autom9-loading">
68	    <p>Loading autom9…</p>
69	  </div>
70	{:else if appStatus === 'error'}
71	  <div class="autom9-error">
72	    <p><strong>autom9 failed to load</strong></p>
73	    <p>{errorMessage}</p>
74	  </div>
75	{:else}
76	  <div class="autom9-shell">
77	    <StatusBar />
78	    {#if isAdminView}
79	      <AdminConfig />
80	    {/if}
81	    <!-- Chat panel and data panel added in Epic 3 stories -->
