1	/**
2	 * Thin wrapper around window.tableau.extensions.initializeAsync().
3	 * Resolves immediately when Tableau runtime is absent (dev/test environment).
4	 */
5	
6	type TableauExtensions = {
7	  extensions: {
8	    initializeAsync: () => Promise<void>;
9	  };
10	};
11	
12	declare global {
13	  interface Window {
14	    tableau?: TableauExtensions;
15	  }
16	}
17	
18	let initialized = false;
19	
20	/**
21	 * Returns the Tableau user identifier from the extension context.
22	 * Falls back to "dev-user" when no Tableau runtime is present (dev/test).
23	 * Must be called AFTER initializeExtension() resolves.
24	 */
25	export function getTableauUserId(): string {
26	  if (typeof window === 'undefined' || !window.tableau) {
27	    return 'dev-user';
28	  }
29	  try {
30	    // tableau.extensions.environment.context is available post-initializeAsync()
31	    const context = (window.tableau.extensions as unknown as {
32	      environment?: { context?: { user?: { userId?: string } } };
33	    }).environment?.context;
34	    return context?.user?.userId ?? 'unknown-user';
35	  } catch {
36	    return 'unknown-user';
37	  }
38	}
39	
40	export async function initializeExtension(): Promise<void> {
41	  if (typeof window === 'undefined' || !window.tableau) {
42	    // No Tableau runtime — running in dev/test outside Tableau Desktop/Cloud.
43	    // Resolve immediately so the extension shell renders normally.
44	    return;
45	  }
46	  if (initialized) return;
47	  await window.tableau.extensions.initializeAsync();
48	  initialized = true;
49	}
